import java.io.*;
import java.net.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.naming.*;
import javax.naming.directory.*;

public class UserLookupServlet extends HttpServlet {
    private DirContext ctx;

    @Override
    public void init() throws ServletException {
        try {
            Hashtable<String, String> env = new Hashtable<>();
            env.put(Context.INITIAL_CONTEXT_FACTORY, "com.sun.jndi.ldap.LdapCtxFactory");
            env.put(Context.PROVIDER_URL, System.getenv("LDAP_URL"));
            env.put(Context.SECURITY_AUTHENTICATION, "simple");
            env.put(Context.SECURITY_PRINCIPAL, System.getenv("LDAP_BIND_DN"));
            env.put(Context.SECURITY_CREDENTIALS, System.getenv("LDAP_BIND_PW"));
            ctx = new InitialDirContext(env);
        } catch (NamingException e) {
            throw new ServletException("LDAP init failed", e);
        }
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String username = req.getParameter("user");
        String department = req.getParameter("dept");
        String format = req.getParameter("format");

        if (username == null || username.isEmpty()) {
            resp.sendError(400, "Missing user parameter");
            return;
        }

        // Basic length check
        if (username.length() > 64 || (department != null && department.length() > 64)) {
            resp.sendError(400, "Parameter too long");
            return;
        }

        // Sanitize format parameter
        if (format != null && !format.matches("^(json|xml|text)$")) {
            format = "json";
        }

        try {
            String filter;
            if (department != null && !department.isEmpty()) {
                // Search by username within department
                filter = "(&(uid=" + username + ")(department=" + department + "))";
            } else {
                filter = "(uid=" + username + ")";
            }

            SearchControls controls = new SearchControls();
            controls.setSearchScope(SearchControls.SUBTREE_SCOPE);
            controls.setReturningAttributes(new String[]{"uid", "cn", "mail", "department", "title"});
            controls.setCountLimit(10);

            NamingEnumeration<SearchResult> results = ctx.search(
                "ou=people,dc=corp,dc=internal", filter, controls);

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.println("{");
            out.println("  \"query\": \"" + escapeJson(username) + "\",");
            out.println("  \"results\": [");

            boolean first = true;
            while (results.hasMore()) {
                SearchResult sr = results.next();
                Attributes attrs = sr.getAttributes();
                if (!first) out.println(",");
                out.println("    {");
                out.println("      \"uid\": \"" + safeAttr(attrs, "uid") + "\",");
                out.println("      \"name\": \"" + safeAttr(attrs, "cn") + "\",");
                out.println("      \"email\": \"" + safeAttr(attrs, "mail") + "\",");
                out.println("      \"department\": \"" + safeAttr(attrs, "department") + "\",");
                out.println("      \"title\": \"" + safeAttr(attrs, "title") + "\"");
                out.println("    }");
                first = false;
            }
            out.println("  ]");
            out.println("}");
        } catch (NamingException e) {
            resp.sendError(500, "Search failed");
        }
    }

    private String safeAttr(Attributes attrs, String name) throws NamingException {
        Attribute attr = attrs.get(name);
        if (attr == null) return "";
        return escapeJson(attr.get().toString());
    }

    private String escapeJson(String s) {
        return s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }
}
